using System.Text.Json;
using System.Text.Json.Serialization;

namespace GeminiGatewayClient.Models;

/// <summary>
/// Response payload returned by the Gemini content generation endpoints.
/// See <see href="https://ai.google.dev/api/generate-content#response-body"/>.
/// </summary>
public sealed class GenerateContentResponse
{
    /// <summary>
    /// Candidate responses generated by the model.
    /// May be empty when the prompt was blocked (inspect <see cref="PromptFeedback"/>).
    /// </summary>
    [JsonPropertyName("candidates")]
    public IList<Candidate> Candidates { get => field ??= []; set; }

    /// <summary>
    /// Optional. Content-filtering metadata and block reason for the input prompt.
    /// </summary>
    [JsonPropertyName("promptFeedback")]
    public PromptFeedback? PromptFeedback { get; set; }

    /// <summary>
    /// Token usage metadata for the request and response.
    /// </summary>
    [JsonPropertyName("usageMetadata")]
    public UsageMetadata? UsageMetadata { get; set; }

    /// <summary>
    /// Identifier and version of the model that produced the response.
    /// </summary>
    [JsonPropertyName("modelVersion")]
    public string? ModelVersion { get; set; }

    /// <summary>
    /// Optional. Unique server-assigned identifier for this generation response.
    /// </summary>
    [JsonPropertyName("responseId")]
    public string? ResponseId { get; set; }

    /// <summary>
    /// Gets or sets additional JSON properties not explicitly modeled by this type.
    /// </summary>
    [JsonExtensionData]
    public IDictionary<string, JsonElement>? ExtensionData { get; set; }

    private IEnumerable<Part> FirstCandidateParts => Candidates.FirstOrDefault()?.Content?.Parts ?? [];

    /// <summary>
    /// Concatenation of all non-thought text parts in the first candidate,
    /// or <c>null</c> when there are no candidates, no parts, or no non-thought text.
    /// </summary>
    [JsonIgnore]
    public string? Text =>
        string.Concat(FirstCandidateParts.Where(part => part is { Thought: not true }).Select(part => part.Text)) is { Length: > 0 } text ? text : null;

    /// <summary>
    /// All function calls requested by the model in the first candidate (empty when there are none).
    /// The model may request several calls in parallel.
    /// </summary>
    [JsonIgnore]
    public IReadOnlyList<FunctionCall> FunctionCalls =>
        [.. FirstCandidateParts.Select(part => part?.FunctionCall).OfType<FunctionCall>()];

    /// <summary>
    /// The <see cref="Models.FinishReason"/> of the first candidate, or <c>null</c> when there are no candidates.
    /// </summary>
    [JsonIgnore]
    public FinishReason? FinishReason => Candidates is { Count: > 0 } c ? c[0]?.FinishReason : null;

    /// <summary>
    /// The prompt-level <see cref="Models.BlockReason"/> when the input was blocked before generation, or <c>null</c>.
    /// </summary>
    [JsonIgnore]
    public BlockReason? BlockReason => PromptFeedback?.BlockReason;

    /// <summary>
    /// <c>true</c> when the prompt or the first candidate response was blocked by safety, recitation, or content filters.
    /// </summary>
    [JsonIgnore]
    public bool IsBlocked =>
        BlockReason is not null and not Models.BlockReason.Unspecified ||
        FinishReason is Models.FinishReason.Safety
            or Models.FinishReason.Recitation
            or Models.FinishReason.BlockList
            or Models.FinishReason.ProhibitedContent
            or Models.FinishReason.Spii
            or Models.FinishReason.ImageSafety
            or Models.FinishReason.ImageProhibitedContent
            or Models.FinishReason.ImageRecitation;
}
